using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class TransformationTimelineOperations : RefCounted
{
    private const float Row=26;
    private static RefCounted? Session(Control owner)=>owner.Get("session").As<RefCounted>();
    private static Resource Document(Control owner)=>Session(owner)!.Get("document").As<Resource>();
    private static GArray Components(Control owner)=>Document(owner).Get("components").AsGodotArray();
    private static bool Contains(GArray values,string id){foreach(var value in values)if(value.AsString()==id)return true;return false;}
    public void ready(Control owner){owner.CustomMinimumSize=new Vector2(300,115);owner.FocusMode=Control.FocusModeEnum.All;owner.MouseFilter=Control.MouseFilterEnum.Stop;owner.ClipContents=true;}
    public double x(Control owner,double time)=>owner.Get("label_width").AsDouble()+time*owner.Get("pixels_per_second").AsDouble()-owner.Get("offset").AsDouble();
    public double time_at(Control owner,double value)=>Math.Clamp((value-owner.Get("label_width").AsDouble()+owner.Get("offset").AsDouble())/owner.Get("pixels_per_second").AsDouble(),0,Document(owner).Get("duration").AsDouble());
    public double row_y(Control owner,int index)=>28+(Components(owner).Count-1-index-owner.Get("vertical").AsInt32())*Row;
    public Settings hit(Control owner,Vector2 point){var components=Components(owner);for(int index=0;index<components.Count;index++){var item=components[index].As<Resource>();float row=(float)row_y(owner,index);foreach(var raw in item.Get("keys").AsGodotArray()){var key=raw.As<Resource>();if(new Vector2((float)x(owner,key.Get("time").AsDouble()),row+Row*.5f).DistanceTo(point)<9)return new Settings {["component"]=item,["key"]=key};}}return new Settings();}
    public void draw(Control owner)
    {
        owner.DrawRect(new Rect2(Vector2.Zero,owner.Size),new Color("101c27"));var session=Session(owner);if(session==null)return;var font=ThemeDB.FallbackFont;double scale=owner.Get("pixels_per_second").AsDouble(),tick=scale>200?.25:scale>60?1:2;float labelWidth=owner.Get("label_width").AsSingle();double duration=Document(owner).Get("duration").AsDouble();for(int index=0;index<Math.Ceiling(duration/tick)+1;index++){float px=(float)x(owner,index*tick);if(px<labelWidth||px>owner.Size.X)continue;owner.DrawLine(new Vector2(px,0),new Vector2(px,owner.Size.Y),new Color(1,1,1,.07f));owner.DrawString(font,new Vector2(px+4,18),(index*tick).ToString("0.##",System.Globalization.CultureInfo.InvariantCulture)+"s",HorizontalAlignment.Left,-1,11,new Color("a5bfca"));}
        var components=Components(owner);for(int index=0;index<components.Count;index++){var item=components[index].As<Resource>();float y=(float)row_y(owner,index);if(y<28||y>=owner.Size.Y)continue;owner.DrawRect(new Rect2(0,y,labelWidth,Row),new Color(Contains(session.Get("selected").AsGodotArray(),item.Get("id").AsString())?"254b48":"1a2b38"));owner.DrawString(font,new Vector2(8,y+18),item.Get("title").AsString(),HorizontalAlignment.Left,labelWidth-16,12,new Color("d6ebe8"));owner.DrawLine(new Vector2(labelWidth,y+Row),new Vector2(owner.Size.X,y+Row),new Color(1,1,1,.08f));foreach(var raw in item.Get("keys").AsGodotArray()){var key=raw.As<Resource>();var point=new Vector2((float)x(owner,key.Get("time").AsDouble()),y+Row*.5f);if(point.X<labelWidth||point.X>owner.Size.X)continue;var color=new Color(Contains(session.Get("selected_keys").AsGodotArray(),key.Get("id").AsString())?"ffce7a":"73dfc4");owner.DrawColoredPolygon(new[]{point+new Vector2(0,-6),point+new Vector2(6,0),point+new Vector2(0,6),point+new Vector2(-6,0)},color);var state=item.Call("state_for_id",key.Get("state_id")).As<Resource>();if(state!=null)owner.DrawString(font,point+new Vector2(10,4),state.Get("title").AsString(),HorizontalAlignment.Left,95,10,new Color("b7c8d2"));}}
        owner.DrawRect(new Rect2(0,0,labelWidth,27),new Color("1b2f3d"));owner.DrawString(font,new Vector2(9,18),"COMPONENT / STATES",HorizontalAlignment.Left,-1,11,new Color("79dac2"));float head=(float)x(owner,session.Get("playhead").AsDouble());if(head>=labelWidth&&head<=owner.Size.X)owner.DrawLine(new Vector2(head,0),new Vector2(head,owner.Size.Y),new Color("ffd18b"),1.5f);
    }
    public void input(Control owner,InputEvent input)
    {
        var session=Session(owner);if(session==null)return;var components=Components(owner);double scale=owner.Get("pixels_per_second").AsDouble(),duration=Document(owner).Get("duration").AsDouble(),labelWidth=owner.Get("label_width").AsDouble();string drag=owner.Get("drag").AsString();var original=owner.Get("original").AsGodotDictionary();
        if(input is InputEventMouseButton mouse)
        {
            if(mouse.Pressed&&mouse.ButtonIndex is MouseButton.WheelUp or MouseButton.WheelDown){int delta=mouse.ButtonIndex==MouseButton.WheelUp?-1:1;if(mouse.CtrlPressed)owner.Set("pixels_per_second",Math.Clamp(scale*(delta<0?1.15:1/1.15),25,600));else if(mouse.ShiftPressed)owner.Set("offset",Math.Clamp(owner.Get("offset").AsDouble()+delta*60,0,Math.Max(0,duration*scale-owner.Size.X+labelWidth)));else owner.Set("vertical",Math.Clamp(owner.Get("vertical").AsInt32()+delta,0,Math.Max(0,components.Count-2)));owner.QueueRedraw();owner.AcceptEvent();return;}if(mouse.ButtonIndex!=MouseButton.Left)return;owner.GrabFocus();if(mouse.Pressed){var found=hit(owner,mouse.Position);if(found.Count>0){var key=found["key"].As<Resource>();var item=found["component"].As<Resource>();string id=key.Get("id").AsString();var chosen=session.Get("selected_keys").AsGodotArray();if(!mouse.CtrlPressed&&!mouse.ShiftPressed&&!Contains(chosen,id))chosen.Clear();if((mouse.CtrlPressed||mouse.ShiftPressed)&&Contains(chosen,id)){for(int index=chosen.Count-1;index>=0;index--)if(chosen[index].AsString()==id)chosen.RemoveAt(index);}else if(!Contains(chosen,id))chosen.Add(id);var selected=session.Get("selected").AsGodotArray();selected.Clear();selected.Add(item.Get("id"));owner.EmitSignal("selection_changed");owner.Set("drag","keys");owner.Set("start",mouse.Position);original=new Settings();owner.Set("original",original);foreach(var raw in components){var component=raw.As<Resource>();foreach(var frameRaw in component.Get("keys").AsGodotArray()){var frame=frameRaw.As<Resource>();if(Contains(chosen,frame.Get("id").AsString())&&!component.Get("locked").AsBool())original[frame.Get("id")]=frame.Get("time");}}if(original.Count>0)session.Call("begin");}else if(mouse.Position.X<labelWidth){int index=components.Count-1-owner.Get("vertical").AsInt32()-(int)((mouse.Position.Y-28)/Row);if(index>=0&&index<components.Count){session.Call("select",components[index].AsGodotObject().Get("id"),false);owner.EmitSignal("selection_changed");}}else{owner.Set("drag","seek");owner.EmitSignal("seek",time_at(owner,mouse.Position.X));}}
            else{if(drag=="keys"&&session.Get("pending").AsGodotDictionary().Count>0){bool valid=Document(owner).Call("validate").AsStringArray().Length==0;if(!valid){session.Call("cancel");session.Set("message","Keys cannot overlap. Move canceled.");}else if(mouse.Position.DistanceTo(owner.Get("start").AsVector2())<1)session.Call("cancel");else session.Call("commit","Move state keys");}owner.Set("drag","");owner.EmitSignal("gesture_finished");}owner.QueueRedraw();owner.AcceptEvent();
        }
        else if(input is InputEventMouseMotion motion){if(drag=="seek")owner.EmitSignal("seek",time_at(owner,motion.Position.X));else if(drag=="keys"){double delta=(motion.Position.X-owner.Get("start").AsVector2().X)/scale;if(!motion.CtrlPressed)delta=Mathf.Snapped(delta,1.0/30);double lo=double.NegativeInfinity,hi=double.PositiveInfinity;foreach(var value in original.Values){double at=value.AsDouble();lo=Math.Max(lo,-at);hi=Math.Min(hi,duration-at);}delta=Math.Clamp(delta,lo,hi);foreach(var raw in components)foreach(var keyRaw in raw.AsGodotObject().Get("keys").AsGodotArray()){var key=keyRaw.As<Resource>();if(original.TryGetValue(key.Get("id"),out var at))key.Set("time",at.AsDouble()+delta);}}owner.QueueRedraw();owner.AcceptEvent();}
        else if(input is InputEventKey key&&key.Pressed&&!key.Echo){if(key.Keycode==Key.Escape&&drag.Length>0){session.Call("cancel");owner.Set("drag","");owner.EmitSignal("gesture_finished");}else if(key.Keycode is Key.Delete or Key.Backspace){session.Call("delete_keys");owner.EmitSignal("selection_changed");}else if(key.CtrlPressed&&key.Keycode==Key.D){session.Call("duplicate_keys");owner.EmitSignal("selection_changed");}else return;owner.QueueRedraw();owner.AcceptEvent();}
    }
}
